199	// setRef points a checkpoint's ref at a new commit and records it for push.
200	// Enqueue is best-effort: a write that lands locally but fails to enqueue must
201	// not fail condensation. The ref is still local; only its remote sync is missed
202	// until a later write to the same checkpoint re-enqueues it.
203	func (s *gitRefsStore) setRef(ctx context.Context, cid id.CheckpointID, hash plumbing.Hash) error {
204		refName, err := RefName(cid)
205		if err != nil {
206			return err
207		}
208		if err := s.repo.Storer.SetReference(plumbing.NewHashReference(refName, hash)); err != nil {
209			return fmt.Errorf("set checkpoint ref %s to %s: %w", refName, hash, err)
210		}
211		s.enqueueForPush(ctx, refName)
212		return nil
213	}
214	
215	// enqueueForPush records refName in the push-discovery queue, logging (never
216	// returning) on failure so the local ref write still succeeds.
217	//
218	// The queue is resolved with the cancellation stripped from ctx. By the time we
219	// get here the ref is already written locally (go-git ref writes don't observe
220	// ctx), and the queue is the ONLY push-discovery mechanism there is — see the
221	// pushQueueFileName doc. A ref that misses the queue is never pushed, and the
222	// writers above are idempotent, so a re-run skips it as already-present and
223	// never re-enqueues it: it stays local-only forever. Resolving the queue shells
224	// out to `git rev-parse --git-common-dir`, which fails instantly on a canceled
225	// ctx, so honoring cancellation here would drop the bookkeeping for a write
226	// that already happened. This local, sub-millisecond step therefore completes
227	// even during shutdown (a second Ctrl-C still force-quits the process).
228	func (s *gitRefsStore) enqueueForPush(ctx context.Context, refName plumbing.ReferenceName) {
229		q, err := PushQueueForRepo(context.WithoutCancel(ctx), s.repo)
230		if err != nil {
231			logging.Warn(ctx, "checkpoint: resolve push queue failed; ref not enqueued",
232				slog.String("ref", refName.String()), slog.String("error", err.Error()))
233			return
234		}
235		if err := q.Enqueue(refName); err != nil {
236			logging.Warn(ctx, "checkpoint: enqueue checkpoint ref for push failed",
237				slog.String("ref", refName.String()), slog.String("error", err.Error()))
238		}
239	}
