241	func (s *gitRefsStore) writeSession(ctx context.Context, opts WriteOptions) error {
242		// Parity with the backfill writers above and with GitStore.writeSession: a
243		// canceled ctx means stop doing work, and creating a checkpoint is the most
244		// expensive write there is (tree building plus a commit). Without this a
245		// bulk writer that ignores cancellation — `entire import` was one — keeps
246		// minting checkpoints after Ctrl-C.
247		if err := ctx.Err(); err != nil {
248			return err //nolint:wrapcheck // Propagating context cancellation
249		}
250		if opts.CheckpointID.IsEmpty() {
251			return errors.New("invalid checkpoint options: checkpoint ID is required")
252		}
253		if err := validation.ValidateSessionID(opts.SessionID); err != nil {
254			return fmt.Errorf("invalid checkpoint options: %w", err)
255		}
256	
257		parentHash, existing, err := s.refBase(opts.CheckpointID)
258		if err != nil {
259			return err
260		}
261	
262		checkpointSubtree, err := s.applySessionWrite(ctx, opts, existing, "")
263		if err != nil {
264			return err
265		}
266	
267		commitMsg := s.buildCommitMessage(opts)
268		commitHash, err := CreateCommit(ctx, s.repo, checkpointSubtree, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail)
269		if err != nil {
270			return err
271		}
272		return s.setRef(ctx, opts.CheckpointID, commitHash)
273	}
