298		commitHash, err := CreateCommit(ctx, s.repo, checkpointSubtree, parentHash, commitMsg, authorName, authorEmail)
299		if err != nil {
300			return err
301		}
302		return s.setRef(ctx, opts.CheckpointID, commitHash)
