20	func transcriptForRecoveryComparison(agentType types.AgentType, transcript redact.RedactedBytes, assets []cpkg.TranscriptAsset) ([]byte, error) {
21		codec := imageextract.CodecFor(agentType)
22		if codec == nil || len(assets) == 0 {
23			return transcript.Bytes(), nil
24		}
25	
26		byName := make(map[string]agent.CompactedTranscriptAsset, len(assets))
27		for _, asset := range assets {
28			byName[asset.Name] = agent.CompactedTranscriptAsset{
29				Name:      asset.Name,
30				MediaType: asset.MediaType,
31				Data:      asset.Data,
32			}
33		}
34		reinjected, err := codec.ReinjectImages(transcript.Bytes(), func(name string) (agent.CompactedTranscriptAsset, bool) {
35			asset, ok := byName[name]
36			return asset, ok
37		})
38		if err != nil {
39			return nil, fmt.Errorf("reinject transcript images: %w", err)
40		}
41		return reinjected, nil
42	}
