44	func findInterruptedCondensation(
45		ctx context.Context,
46		store cpkg.PersistentStore,
47		state *SessionState,
48		transcript redact.RedactedBytes,
49		assets []cpkg.TranscriptAsset,
50	) (id.CheckpointID, bool, error) {
51		expectedTranscript, err := transcriptForRecoveryComparison(state.AgentType, transcript, assets)
52		if err != nil {
53			return id.EmptyCheckpointID, false, err
54		}
55	
56		checkpoints, err := store.List(ctx)
57		if err != nil {
58			return id.EmptyCheckpointID, false, fmt.Errorf("list checkpoints: %w", err)
59		}
60		var candidateErrors []error
61		for _, info := range checkpoints {
62			if info.ListedStub || (info.SessionID != state.SessionID && !slices.Contains(info.SessionIDs, state.SessionID)) {
63				continue
64			}
65			summary, readErr := store.Read(ctx, info.CheckpointID)
66			if readErr != nil {
67				candidateErrors = append(candidateErrors, fmt.Errorf("read checkpoint %s: %w", info.CheckpointID, readErr))
68				continue
69			}
70			if summary == nil {
71				candidateErrors = append(candidateErrors, fmt.Errorf("read checkpoint %s: %w", info.CheckpointID, cpkg.ErrCheckpointNotFound))
72				continue
73			}
74			for sessionIndex := range len(summary.Sessions) {
75				metadata, metadataErr := store.ReadSessionMetadata(ctx, info.CheckpointID, sessionIndex)
76				if metadataErr != nil {
77					candidateErrors = append(candidateErrors, fmt.Errorf("read checkpoint %s session %d metadata: %w", info.CheckpointID, sessionIndex, metadataErr))
78					continue
79				}
80				if metadata == nil {
81					candidateErrors = append(candidateErrors, fmt.Errorf("read checkpoint %s session %d metadata: %w", info.CheckpointID, sessionIndex, cpkg.ErrCheckpointNotFound))
82					continue
83				}
84				if metadata.SessionID != state.SessionID ||
85					metadata.Strategy != StrategyNameManualCommit ||
86					metadata.CheckpointTranscriptStart != state.CheckpointTranscriptStart ||
87					metadata.TranscriptIdentifierAtStart != state.TranscriptIdentifierAtStart ||
88					metadata.CheckpointsCount != checkpointStepCount(state) ||
89					metadata.SaveStepCount != state.StepCount ||
90					metadata.Agent != state.AgentType ||
91					metadata.TurnID != state.TurnID ||
92					metadata.Kind != string(state.Kind) ||
93					len(metadata.FilesTouched) != 0 {
94					continue
95				}
96				content, contentErr := store.ReadSessionContent(ctx, info.CheckpointID, sessionIndex)
97				if contentErr != nil {
98					candidateErrors = append(candidateErrors, fmt.Errorf("read checkpoint %s session %d content: %w", info.CheckpointID, sessionIndex, contentErr))
99					continue
100				}
101				if content == nil {
102					candidateErrors = append(candidateErrors, fmt.Errorf("read checkpoint %s session %d content: %w", info.CheckpointID, sessionIndex, cpkg.ErrCheckpointNotFound))
103					continue
104				}
105				if bytes.Equal(content.Transcript, expectedTranscript) {
106					return info.CheckpointID, true, nil
107				}
108			}
109		}
110		if len(candidateErrors) > 0 {
111			return id.EmptyCheckpointID, false, errors.Join(candidateErrors...)
112		}
113		return id.EmptyCheckpointID, false, nil
114	}
