10	// fanoutStore serves all reads from the primary and fans writes out to the
11	// primary plus zero or more mirror backends. The primary is the source of
12	// truth: a write fails only if the primary write fails. Mirror writes are
13	// best-effort — a mirror failure is logged and swallowed so it can never break
14	// a checkpoint operation. Mirrors are therefore write-only and may legitimately
15	// lag the primary (they never receive ref-level mutations such as cleanup
16	// deletes or pre-push OPF re-redaction); they must not be promoted to a read or
17	// sync source without separate reconciliation.
18	type fanoutStore struct {
19		primary PersistentStore
20		mirrors []Writer
21	}
22	
23	// newFanoutStore wraps a primary with mirror write fan-out. With no mirrors it
24	// returns the primary unchanged, so the common (no-mirror) path keeps the
25	// concrete store and all of its optional capabilities. When wrapping is needed,
26	// it preserves the optional AuthorReader capability iff the primary has it.
27	func newFanoutStore(primary PersistentStore, mirrors []Writer) PersistentStore {
28		if len(mirrors) == 0 {
29			return primary
30		}
31		base := &fanoutStore{primary: primary, mirrors: mirrors}
32		if author, ok := primary.(AuthorReader); ok {
33			return &fanoutStoreWithAuthor{fanoutStore: base, author: author}
34		}
35		return base
36	}
37	
38	// The read methods are pure delegation to the primary; nolint:wrapcheck because
39	// re-wrapping the primary's errors here would add noise without context (same
40	// convention as the contract re-exports in aliases.go).
41	
42	func (s *fanoutStore) Read(ctx context.Context, checkpointID id.CheckpointID) (*CheckpointSummary, error) {
43		return s.primary.Read(ctx, checkpointID) //nolint:wrapcheck // pure delegation to primary
44	}
45	
46	func (s *fanoutStore) List(ctx context.Context) ([]CheckpointInfo, error) {
47		return s.primary.List(ctx) //nolint:wrapcheck // pure delegation to primary
48	}
49	
50	func (s *fanoutStore) ReadSessionContent(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error) {
51		return s.primary.ReadSessionContent(ctx, checkpointID, sessionIndex) //nolint:wrapcheck // pure delegation to primary
52	}
53	
54	func (s *fanoutStore) ReadSessionMetadata(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*Metadata, error) {
55		return s.primary.ReadSessionMetadata(ctx, checkpointID, sessionIndex) //nolint:wrapcheck // pure delegation to primary
56	}
57	
58	func (s *fanoutStore) ReadSessionPrompts(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (string, error) {
59		return s.primary.ReadSessionPrompts(ctx, checkpointID, sessionIndex) //nolint:wrapcheck // pure delegation to primary
60	}
61	
62	func (s *fanoutStore) ReadSessionMetadataAndPrompts(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*Metadata, string, error) {
63		return s.primary.ReadSessionMetadataAndPrompts(ctx, checkpointID, sessionIndex) //nolint:wrapcheck // pure delegation to primary
64	}
65	
66	// Write applies to the primary first; only on primary success does it fan out to
67	// each mirror best-effort. A mirror error is logged and dropped.
68	func (s *fanoutStore) Write(ctx context.Context, req WriteRequest) error {
69		if err := s.primary.Write(ctx, req); err != nil {
70			return err //nolint:wrapcheck // primary error is the operation's error, surfaced verbatim
71		}
72		for i, mirror := range s.mirrors {
73			if err := mirror.Write(ctx, req); err != nil {
74				logging.Warn(ctx, "checkpoint mirror write failed; primary write succeeded",
75					"mirror_index", i, "error", err.Error())
76			}
77		}
78		return nil
79	}
80	
81	// fanoutStoreWithAuthor adds the optional AuthorReader capability when the
82	// wrapped primary supports it, so callers that type-assert the store to
83	// AuthorReader (e.g. explain's author fallback) keep working through the wrapper.
84	type fanoutStoreWithAuthor struct {
85		*fanoutStore
86	
87		author AuthorReader
88	}
89	
90	func (s *fanoutStoreWithAuthor) GetCheckpointAuthor(ctx context.Context, checkpointID id.CheckpointID) (Author, error) {
91		return s.author.GetCheckpointAuthor(ctx, checkpointID) //nolint:wrapcheck // pure delegation to primary
92	}
93	
94	var (
95		_ PersistentStore = (*fanoutStore)(nil)
96		_ PersistentStore = (*fanoutStoreWithAuthor)(nil)
97		_ AuthorReader    = (*fanoutStoreWithAuthor)(nil)
98	)
