	worktreeID, err := paths.GetWorktreeID(dir)
	if err != nil {
		t.Fatalf("worktree ID: %v", err)
	}

	stateDir := filepath.Join(dir, ".git", session.SessionStateDirName)
	if err := os.MkdirAll(stateDir, 0o755); err != nil {
		t.Fatalf("mkdir state dir: %v", err)
	}
	store := session.NewStateStoreWithDir(stateDir)

	agentTypes := []types.AgentType{
		agent.AgentTypeClaudeCode,
		agent.AgentTypeClaudeCode,
		agent.AgentTypeClaudeCode,
		agent.AgentTypeGemini,
		agent.AgentTypeOpenCode,
	}

	s := &ManualCommitStrategy{}

	// Real-world distribution (from .git/entire-sessions/ analysis):
	//   ~75% have shadow branches with data but no LastCheckpointID (not yet committed)
	//   ~25% have LastCheckpointID set and no shadow branch (already committed)
	//
	// The 75% exercise the expensive hot path per session:
	//   listAllSessionStates: packed-refs linear scan to resolve shadow branch ref
	//   sessionHasNewContent: ref → commit → tree → transcript/overlap check
	//   PostCommit condensation: write metadata to entire/checkpoints/v1 branch
	endedWithShadow := ended * 3 / 4
	endedWithoutShadow := ended - endedWithShadow

	fixture := hookPerfFixture{
		endedWithShadow: seedEndedShadowSessions(t, s, dir, store, worktreeID, baseCommits, agentTypes, endedWithShadow),
	}
	seedEndedCommittedSessions(t, store, worktreeID, baseCommits, agentTypes, endedWithShadow, endedWithoutShadow)
	seedIdleSessions(t, s, dir, agentTypes, idle)
	seedActiveSessions(t, s, dir, agentTypes, active)

	// Count unique base commits actually used.
	seen := make(map[string]struct{})
	states, err := store.List(ctx)
	if err != nil {
		t.Fatalf("list states: %v", err)
	}
	for _, st := range states {
		seen[st.BaseCommit] = struct{}{}
	}

	t.Logf("  Seeded %d sessions (ended=%d [%d shadow, %d committed], idle=%d, active=%d), %d unique base commits",
		len(states), ended, endedWithShadow, endedWithoutShadow, idle, active, len(seen))
	return fixture
}

// seedEndedShadowSessions seeds the ENDED sessions that still have a shadow
// branch (no LastCheckpointID) — the expensive PostCommit condensation path.
func seedEndedShadowSessions(
	t *testing.T,
	s *ManualCommitStrategy,
	dir string,
	store *session.StateStore,
	worktreeID string,
	baseCommits []string,
	agentTypes []types.AgentType,
	count int,
) []hookPerfEndedSession {
	t.Helper()
	if count == 0 {
		return nil
	}
	ctx := context.Background()

	repo, openErr := gitrepo.OpenPath(dir)
	if openErr != nil {
		t.Fatalf("open repo for shadow checkpoints: %v", openErr)
	}
	defer func() {
		if closeErr := repo.Close(); closeErr != nil {
			t.Fatalf("close repo after shadow checkpoints: %v", closeErr)
		}
	}()
	ephemeral, storeErr := s.getEphemeralStore(ctx, repo)
	if storeErr != nil {
		t.Fatalf("open ephemeral store: %v", storeErr)
	}

	sessions := make([]hookPerfEndedSession, 0, count)
	for i := range count {
		sessionID := fmt.Sprintf("perf-ended-%d", i)
		base := baseCommits[i]
		metadataDir := paths.SessionMetadataDirFromSessionID(sessionID)
		metadataDirAbs := filepath.Join(dir, metadataDir)
		if mkdirErr := os.MkdirAll(metadataDirAbs, 0o755); mkdirErr != nil {
			t.Fatalf("mkdir ended metadata %d: %v", i, mkdirErr)
		}
		transcript := fmt.Sprintf("{\"type\":\"human\",\"message\":{\"content\":%q}}\n{\"type\":\"assistant\",\"message\":{\"content\":%q}}\n",
			perfPrompts[i%len(perfPrompts)], "completed work for "+sessionID)
		if writeErr := os.WriteFile(filepath.Join(metadataDirAbs, paths.TranscriptFileName), []byte(transcript), 0o644); writeErr != nil {
			t.Fatalf("write ended transcript %d: %v", i, writeErr)
		}

		result, writeErr := ephemeral.Write(ctx, checkpoint.Step{
			SessionID:         sessionID,
			BaseCommit:        base,
			WorktreeID:        worktreeID,
			NewFiles:          []string{"perf_control.txt"},
			MetadataDir:       metadataDir,
			MetadataDirAbs:    metadataDirAbs,
			CommitMessage:     "Checkpoint 1",
			AuthorName:        "Perf",
			AuthorEmail:       "perf@test.com",
			IsFirstCheckpoint: true,
		})
		if writeErr != nil {
			t.Fatalf("write ended shadow checkpoint %d: %v", i, writeErr)
		}
		if result.Skipped {
			t.Fatalf("ended shadow checkpoint %d was unexpectedly skipped", i)
		}

		now := time.Now()
		endedAt := now.Add(-time.Duration((i%144)+1) * time.Hour)
		state := &session.State{
			SessionID:             sessionID,
			CLIVersion:            "dev",
			BaseCommit:            base,
			AttributionBaseCommit: base,
			WorktreePath:          dir,
			WorktreeID:            worktreeID,
			Phase:                 session.PhaseEnded,
			StartedAt:             endedAt.Add(-time.Hour),
			EndedAt:               &endedAt,
			StepCount:             (i % 5) + 1,
			FilesTouched:          perfLargeFileSets[i%len(perfLargeFileSets)],
			LastInteractionTime:   &now,
			AgentType:             agentTypes[i%len(agentTypes)],
			LastPrompt:            perfPrompts[i%len(perfPrompts)],
		}
		if saveErr := store.Save(ctx, state); saveErr != nil {
			t.Fatalf("save ended-shadow state %d: %v", i, saveErr)
		}

		shadowName := checkpoint.ShadowBranchNameForCommit(base, worktreeID)
		sessions = append(sessions, hookPerfEndedSession{
			sessionID:  sessionID,
			baseCommit: base,
			shadowRef:  plumbing.NewBranchReferenceName(shadowName),
		})
	}
	return sessions
}

// seedEndedCommittedSessions seeds the ENDED sessions that are already
// committed (state file with LastCheckpointID, no shadow branch) — the cheap
// PostCommit no-op path. sessionIndexOffset numbers sessions after those
// already created by seedEndedShadowSessions.
func seedEndedCommittedSessions(
	t *testing.T,
	store *session.StateStore,
	worktreeID string,
	baseCommits []string,
	agentTypes []types.AgentType,
	sessionIndexOffset, count int,
) {
	t.Helper()
	ctx := context.Background()

	for i := range count {
		idx := sessionIndexOffset + i
		sessionID := fmt.Sprintf("perf-ended-%d", idx)
		cpID := mustGenerateCheckpointID(t)
		now := time.Now()
		baseIdx := (idx + 1) % len(baseCommits)
		base := baseCommits[baseIdx]

		state := &session.State{
			SessionID:           sessionID,
			CLIVersion:          "dev",
			BaseCommit:          base,
			WorktreeID:          worktreeID,
			Phase:               session.PhaseEnded,
			StartedAt:           now.Add(-time.Duration((idx%144)+1) * time.Hour),
			LastCheckpointID:    cpID,
			StepCount:           (idx % 5) + 1,
			FilesTouched:        perfLargeFileSets[idx%len(perfLargeFileSets)],
			LastInteractionTime: &now,
			AgentType:           agentTypes[idx%len(agentTypes)],
			LastPrompt:          perfPrompts[idx%len(perfPrompts)],
		}
		if saveErr := store.Save(ctx, state); saveErr != nil {
			t.Fatalf("save ended-committed state %d: %v", i, saveErr)
		}
	}
}

// seedIdleSessions seeds IDLE sessions, each with a shadow branch checkpoint.
func seedIdleSessions(t *testing.T, s *ManualCommitStrategy, dir string, agentTypes []types.AgentType, count int) {
	t.Helper()
	ctx := context.Background()

	for i := range count {
		sessionID := fmt.Sprintf("perf-idle-%d", i)
		files := perfFileSets[i%len(perfFileSets)]
		seedSessionWithShadowBranch(t, s, dir, sessionID, session.PhaseIdle, files)

		// Enrich state with unique data.
		state, loadErr := s.loadSessionState(ctx, sessionID)
		if loadErr != nil {
			t.Fatalf("load idle state %d: %v", i, loadErr)
		}
		state.AgentType = agentTypes[i%len(agentTypes)]
		state.LastPrompt = perfPrompts[i%len(perfPrompts)]
		state.StepCount = (i % 3) + 1
		if saveErr := s.saveSessionState(ctx, state); saveErr != nil {
			t.Fatalf("save idle state %d: %v", i, saveErr)
		}
	}
}

// seedActiveSessions seeds ACTIVE sessions, each with a shadow branch and a
// live agent transcript file.
func seedActiveSessions(t *testing.T, s *ManualCommitStrategy, dir string, agentTypes []types.AgentType, count int) {
	t.Helper()
	ctx := context.Background()

	for i := range count {
		sessionID := fmt.Sprintf("perf-active-%d", i)
		files := perfFileSets[i%len(perfFileSets)]
		seedSessionWithShadowBranch(t, s, dir, sessionID, session.PhaseActive, files)

		// Create a live transcript file with varied content.
		claudeProjectDir := filepath.Join(dir, ".claude", "projects", "test", "sessions")
		if mkdirErr := os.MkdirAll(claudeProjectDir, 0o755); mkdirErr != nil {
			t.Fatalf("mkdir claude sessions: %v", mkdirErr)
		}
		prompt := perfPrompts[i%len(perfPrompts)]
		transcript := fmt.Sprintf(`{"type":"human","message":{"content":"%s"}}
{"type":"assistant","message":{"content":"I'll work on that for you. Let me start by examining the codebase."}}
{"type":"tool_use","name":"read","input":{"path":"%s"}}
{"type":"tool_use","name":"write","input":{"path":"%s","content":"package main\n// modified by session %d\nfunc main() {}\n"}}
`, prompt, files[0], files[0], i)
		transcriptFile := filepath.Join(claudeProjectDir, sessionID+".jsonl")
		if writeErr := os.WriteFile(transcriptFile, []byte(transcript), 0o644); writeErr != nil {
			t.Fatalf("write live transcript: %v", writeErr)
		}

		state, loadErr := s.loadSessionState(ctx, sessionID)
		if loadErr != nil {
			t.Fatalf("load active state %d: %v", i, loadErr)
		}
		state.AgentType = agentTypes[i%len(agentTypes)]
		state.LastPrompt = prompt
		state.TranscriptPath = transcriptFile
		if saveErr := s.saveSessionState(ctx, state); saveErr != nil {
			t.Fatalf("save active state %d: %v", i, saveErr)
		}
	}
}

